import React, { useState } from "react";
import axios from "axios";

function App() {
  const [file, setFile] = useState(null);
  const [question, setQuestion] = useState("");
  const [answer, setAnswer] = useState("");
  const [uploadStatus, setUploadStatus] = useState("");

  const handleFileChange = (e) => {
    setFile(e.target.files[0]);
  };

  const handleUpload = async () => {
    if (!file) return alert("Please select a file first");
    const formData = new FormData();
    formData.append("file", file);

    try {
      const res = await axios.post("http://127.0.0.1:8000/upload", formData);
      console.log("Upload response:", res.data);

      // Fallback if "sheets" key doesn't exist
      if (res.data.sheets) {
        setUploadStatus("File uploaded successfully: " + res.data.sheets.join(", "));
      } else if (res.data.filename) {
        setUploadStatus("File uploaded successfully: " + res.data.filename);
      } else if (res.data.success) {
        setUploadStatus("File uploaded successfully");
      } else {
        setUploadStatus("File uploaded: " + JSON.stringify(res.data));
      }
    } catch (err) {
      console.error(err);
      setUploadStatus("Upload failed: " + (err.response?.data?.error || err.message));
    }
  };

  const handleAsk = async () => {
    if (!question) return alert("Please type a question first");

    try {
      const res = await axios.post(
        "http://127.0.0.1:8000/ask",
        new URLSearchParams({ question }),
        { headers: { "Content-Type": "application/x-www-form-urlencoded" } }
      );
      console.log("Ask response:", res.data);

      // Fallbacks if "answer" key doesn't exist
      setAnswer(res.data.answer || res.data.result || JSON.stringify(res.data));
    } catch (err) {
      console.error(err);
      setAnswer("Error: " + (err.response?.data?.error || err.message));
    }
  };

  return (
    <div style={{ padding: "20px", fontFamily: "Arial" }}>
      <h2>AI Data Agent</h2>

      <div>
        <input type="file" onChange={handleFileChange} />
        <button onClick={handleUpload} style={{ marginLeft: "10px" }}>
          Upload
        </button>
      </div>
      <p>{uploadStatus}</p>

      <div style={{ marginTop: "20px" }}>
        <input
          type="text"
          value={question}
          onChange={(e) => setQuestion(e.target.value)}
          placeholder="Ask a question..."
          style={{ width: "300px" }}
        />
        <button onClick={handleAsk} style={{ marginLeft: "10px" }}>
          Ask
        </button>
      </div>

      {answer && (
        <div style={{ marginTop: "20px", whiteSpace: "pre-wrap" }}>
          <h4>AI Answer:</h4>
          <p>{answer}</p>
        </div>
      )}
    </div>
  );
}

export default App;
